import { useState } from 'react';
import { registerUser } from './api';
import './register.css';

function Register({ onLogin, onSuccess }) {
    const [showPasswords, setShowPasswords] = useState(false);
    const [error, setError] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);

    async function handleSubmit(event) {
        event.preventDefault();
        setError('');
        const form = event.currentTarget;
        if (form.password.value !== form.confirmPassword.value) {
            setError('Passwords do not match');
            return;
        }
        setIsSubmitting(true);
        try {
            const response = await registerUser({
                fullname: form.name.value,
                username: form.username.value,
                email: form.email.value,
                password: form.password.value,
                    role: form.role.value,
            });
            onSuccess(response.data.user);
        } catch (submitError) {
            setError(submitError.message);
        } finally {
            setIsSubmitting(false);
        }
    }

    return (
        <main className="register-page">
            <section className="register-card" aria-labelledby="register-title">
                <h1 id="register-title">Create Account</h1>
                <p className="subtitle">Register to start managing your tasks</p>

                <form onSubmit={handleSubmit}>
                    <label htmlFor="name">Name</label>
                    <input id="name" name="name" type="text" placeholder="Enter your name" autoComplete="name" required />

                    <label htmlFor="register-email">Email</label>
                    <input id="register-email" name="email" type="email" placeholder="Enter your email" autoComplete="email" required />

                    <label htmlFor="username">Username</label>
                    <input id="username" name="username" type="text" placeholder="Choose a username" autoComplete="username" required />

                        <label htmlFor="register-role">Account type</label>
                        <select id="register-role" name="role" defaultValue="User">
                            <option value="User">User</option>
                            <option value="Manager">Manager</option>
                        </select>

                    <label htmlFor="register-password">Password</label>
                    <div className="password-box">
                        <input id="register-password" name="password" type={showPasswords ? 'text' : 'password'} placeholder="Create a password" autoComplete="new-password" required />
                        <button type="button" onClick={() => setShowPasswords(!showPasswords)}>{showPasswords ? 'Hide' : 'Show'}</button>
                    </div>

                    <label htmlFor="confirm-password">Confirm Password</label>
                    <input id="confirm-password" name="confirmPassword" type={showPasswords ? 'text' : 'password'} placeholder="Confirm your password" autoComplete="new-password" required />

                    {error && <p className="message error-message" role="alert">{error}</p>}
                    <button className="register-button" type="submit" disabled={isSubmitting}>{isSubmitting ? 'Creating account...' : 'Register'}</button>
                </form>

                <p className="login-text">Already have an account? <button className="link-button" type="button" onClick={onLogin}>Login here</button></p>
            </section>
        </main>
    );
}

export default Register;
